SourceCode.Declaration:
/// <summary>
/// Service class for TMS engine processing.
/// </summary>
class METTMSEngineProcessingService extends METSysOperationService
{
    private guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Returns name of the task service class.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METTMSEngineProcessingTaskService);
}

/// <summary>
/// Returns name of the task service class method.
/// </summary>
/// <returns>Task service class method name</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METTMSEngineProcessingTaskService, process);
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METTMSEngineProcessingContract</c>
/// </param>
public void process(METTMSEngineProcessingContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Initialise global variables.
/// </summary>
public void initialise()
{
    super();

    this.stageDataIntoQueue();
}

/// <summary>
/// Stages data in queue.
/// </summary>
void stageDataIntoQueue()
{
    #OCCRetryCount

    METTMSProcessingStatus         tmsProcessingStatus;
    METTMSEngineProcessingQueue    tmsEngineProcessingQueue;
    METTMSEngineProcessingTmp      tmsEngineProcessingTmp,
                                   tmsEngineProcessingTmpFiltered;
    METTMSEngineProcessingContract contract;

    contract = dataContract as METTMSEngineProcessingContract;
    topPickingProcessId = newGuid();

    try
    {
        ttsbegin;

        METTMSEngineProcessingQueue::cleanUpQueue();

        METTMSEngineProcessingTmp::insertDataFromQuery(tmsEngineProcessingTmp, contract.getQuery());

        insert_recordset tmsEngineProcessingTmpFiltered (DocumentNumber, OrderType, TMSEngineProcessingStatusDateTime)
            select DocumentNumber, OrderType, maxof(TMSEngineProcessingStatusDateTime) from tmsEngineProcessingTmp
                group by DocumentNumber, OrderType;

        insert_recordset tmsEngineProcessingQueue(DocumentNumber, ExecutionMode, OrderType, ProcessId)
            select DocumentNumber, ExecutionMode, OrderType, topPickingProcessId from tmsEngineProcessingTmp
                exists join tmsEngineProcessingTmpFiltered
                    where tmsEngineProcessingTmpFiltered.DocumentNumber == tmsEngineProcessingTmp.DocumentNumber
                    &&    tmsEngineProcessingTmpFiltered.OrderType == tmsEngineProcessingTmp.OrderType
                    &&    tmsEngineProcessingTmpFiltered.TMSEngineProcessingStatusDateTime == tmsEngineProcessingTmp.TMSEngineProcessingStatusDateTime;

        while select forupdate tmsProcessingStatus
                where tmsProcessingStatus.Status != METTMSSyncStatus::Cancelled
            exists join tmsEngineProcessingQueue
                where tmsEngineProcessingQueue.OrderType == tmsProcessingStatus.OrderType
                &&    tmsEngineProcessingQueue.DocumentNumber == tmsProcessingStatus.DocumentNumber
                &&    tmsEngineProcessingQueue.ExecutionMode != tmsProcessingStatus.ExecutionMode
                &&    tmsEngineProcessingQueue.ProcessId == topPickingProcessId
        {
            tmsProcessingStatus.Status = METTMSSyncStatus::Cancelled;
            tmsProcessingStatus.update();
        }

        ttscommit;

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        // catch the errors so processing can continue
        exceptionTextFallThrough();
    }

}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METTMSEngineProcessingContract contract = _taskDataContract as METTMSEngineProcessingContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METTMSEngineProcessingContract();
}
